// fnv1a: the 64-bit FNV-1a hash of 8 MiB of generated bytes (printed as a
// signed 64-bit number, as Mimic's i64 prints it).

fn main() {
    let n: i64 = 1 << 23;
    let data: Vec<u8> = (0..n).map(|i| ((i * 2654435761 >> 13) & 255) as u8).collect();
    let h = data.iter().fold(0xcbf29ce484222325u64, |h, &b| (h ^ b as u64).wrapping_mul(0x100000001b3));
    println!("{}", h as i64);
}
